'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict');
const H=require('./helpers/3580-battle.cjs');
const {source,key,IDLE,WAIT,HIT,FEAR,make,turn,wait,timer,allStages,pick,seedCase}=H;
const hp=s=>s.fighters.map(f=>f.hp);
const cursed=f=>Object.keys(f.ailments).some(k=>k.includes('诅咒'));

test('3580 消强1055与988成功后下回合封攻或封全部、失败和到期',()=>{
  for(const id of [1055,988]){const e=pick(id)[0],s=make(e);s.fighters[1].stages.atk=2;s.fighters[1].stages.def=-1;let o=turn(s,e.moveId,HIT);assert.equal(o.fighters[1].stages.atk,0);assert.equal(o.fighters[1].stages.def,-1);assert.ok(o.fighters[0].hp<9000);const before=o.fighters[0].hp;o=turn(o,IDLE,HIT);assert.equal(o.fighters[0].hp,before);assert.ok(turn(o,IDLE,HIT).fighters[0].hp<before);
    assert.equal(turn(make(e)).fighters[1].effects[id===988?'skillBlock':'attackBlock'],undefined);
    const st=make(e,{opponentBoost:true});st.fighters[1].stages.atk=1;const b=turn(turn(st),IDLE,900023);assert.equal(b.fighters[1].stages.atk,id===988?0:2);
  }
});
test('3580 满血925威力翻倍与残血边界、失误',()=>{
  const e=pick(925)[0];const yes=turn(make(e)),no=turn(make(e,{hp:8999})),control=turn(make(e,{omit:true}));assert.equal(no.fighters[0].lastAttackDamage,control.fighters[0].lastAttackDamage);assert.ok(yes.fighters[0].lastAttackDamage>no.fighters[0].lastAttackDamage*1.8);const miss=make(e,{hit:false});timer(miss,0,'攻击必失');assert.equal(turn(miss).fighters[1].hp,9000);
});
test('3580 固伤29追加75、攻击免疫不免固伤且失误不追加',()=>{
  const e=pick(29)[0],o=turn(make(e));assert.equal(9000-o.fighters[1].hp-o.fighters[0].lastAttackDamage,75);const immune=make(e);timer(immune,1,'鬼王攻击免疫');assert.equal(turn(immune).fighters[1].hp,8925);timer(immune,1,'当回合免伤');assert.equal(turn(immune).fighters[1].hp,9000);const miss=make(e,{hit:false});timer(miss,0,'攻击必失');assert.equal(turn(miss).fighters[1].hp,9000);
});
test('3580 清弱3保留正等级、无弱化与封招',()=>{
  const e=pick(3)[0],s=make(e);s.fighters[0].stages.atk=-6;s.fighters[0].stages.def=2;const o=turn(s);assert.equal(o.fighters[0].stages.atk,0);assert.equal(o.fighters[0].stages.def,2);assert.equal(turn(make(e)).fighters[0].stages.atk,0);timer(s,0,'skillBlock');assert.equal(turn(s).fighters[0].stages.atk,-6);
});
test('3580 弱化590真实15%双倍分支、下限和免弱',()=>{
  const e=pick(590)[0],normal=seedCase(e,o=>o.fighters[1].stages.atk===-1),double=seedCase(e,o=>o.fighters[1].stages.atk===-2);for(const [found,n] of [[normal,-1],[double,-2]])assert.deepEqual(Object.values(found.out.fighters[1].stages),Array(6).fill(n));const cap=make(e,{seed:double.seed});allStages(cap,1,-6);assert.deepEqual(Object.values(turn(cap).fighters[1].stages),Array(6).fill(-6));const block=make(e);timer(block,1,'免弱');assert.deepEqual(Object.values(turn(block).fighters[1].stages),Array(6).fill(0));
