 const chart=mergeCharts(snapshots);
 if(chart){for(let i=0;i<2;i++){effectiveness(snapshots[i].type,snapshots[1-i].type,chart);for(const id of checks[i].selected){const m=snapshots[i].moves.find(m=>m.id===id);if(m.kind!=='status')effectiveness(m.type,snapshots[1-i].type,chart);}}}
 else if(new Set(snapshots.map(s=>s.id)).size!==2)throw new Error('同种对战需要通用属性克制表');
 if(snapshots[0].id===snapshots[1].id&&JSON.stringify(snapshots[0].base)!==JSON.stringify(snapshots[1].base))throw new Error('同种精灵种族值版本不一致');
 const additions={},speciesAdditions={};
 for(let i=0;i<2;i++){const s=snapshots[i],c=checks[i],p=c.profile;
 for(const k of ['maxHp','atk','def','spa','spd','spe'])if(!Number.isInteger(s.base[k])||s.base[k]<1||s.base[k]>999)throw new Error('种族值无效');
 if(!chart&&s.type!==(p.key==='emperor'?'自然圣灵':'电'))throw new Error('在线属性已变化，需要核对克制表');
 const keys=[];for(const id of c.selected){const m=s.moves.find(m=>m.id===id),key=(m.provider!=='seerapi'?registry[id]?.[0]:null)??'wiki:'+id;keys.push(key);const move={...E.MOVES[key],id:key,name:m.name,kind:m.kind,category:{physical:'物理',special:'特殊',status:'属性'}[m.kind],type:m.kind==='status'?'属性':m.type,power:m.power,pp:m.pp,accuracy:m.accuracy,alwaysHit:m.alwaysHit,priority:m.priority,description:m.description+(compile(m,s).experimental.length?'；实验规则：'+compile(m,s).experimental.join('；'):''),wikiId:m.id,...(m.hiddenEffect?{hiddenEffect:m.hiddenEffect}:{}),effectIds:m.effectIds,revision:m.revision,criticalChance:Number(m.critical?.split('/')[0]??1)/16,deferredEffects:compile(m,s).deferred,operations:compile(m,s).operations};if(additions[key]&&JSON.stringify(additions[key])!==JSON.stringify(move))throw new Error('同一技能数据版本不一致');additions[key]=move;}
 speciesAdditions[p.key]={...E.SPECIES[p.key],name:s.name,number:String(s.id),base:{...(s.souls.find(x=>x.id===p.soul)?.base??s.base)},type:s.type,moves:keys,soulId:p.soul,maxHpMultiplier:E.SOULS.registry[p.soul]?.traits.maxHpMultiplier??1,speedGrowthToHp:!!E.SOULS.registry[p.soul]?.traits.speedGrowthToHp,soul:p.soul?E.SOULS.registry[p.soul]?.name:undefined,soulText:s.souls.find(x=>x.id===p.soul)?.description.replace(/<[^>]*>/g,' ')??''};
 }
 E.MOVES=Object.freeze({...E.MOVES,...additions});Object.assign(E.SPECIES,speciesAdditions);return checks.map((c,i)=>({species:c.profile.key,typeChart:chart,moves:c.selected.map(id=>(snapshots[i].source?.provider!=='seerapi'?registry[id]?.[0]:null)??'wiki:'+id)}));
}
return {effectsEngine,registry,profiles,profileFor,slotCount,defaultMoves,compile,effectiveness,moveIssue,assess,prepare,verified,fingerprint};
});

