const base='https://api.seerapi.com/v1/';
async function transport(url){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),30000);try{const r=await fetch(url,{signal:ctl.signal,headers:{'Accept':'application/json','User-Agent':'SeerBattleLab/0.8 (personal battle simulator; read-only data client)'}});let body=null;try{body=await r.json();}catch{throw new Error('SeerAPI 返回格式错误');}return {status:r.status,retryAfter:r.headers.get('retry-after')||'',body};}catch(e){if(e.name==='AbortError')throw new Error('SeerAPI 查询超时');throw new Error('SeerAPI 连接失败：'+e.message);}finally{clearTimeout(timer);}}
