function api(resource,id,params={}){if(!['pet','skill','skill_effect_type','element_type','element_type_combination','soulmark'].includes(resource)||id!=null&&!/^\d+$/.test(String(id)))throw new Error('资源请求无效');return client.request(base+resource+'/'+(id??'')+'?'+new URLSearchParams(params));}
