function int(n,label,min=0,max=999999){if(!Number.isInteger(n)||n<min||n>max)throw new Error('SeerAPI '+label+'无效');return n;}
function buildChart(data){const names=Object.fromEntries(data.results.map(t=>[t.id,t.name])),rows={},aliases={};for(const t of data.results){rows[t.name]={};aliases[t.name]=[t.name];for(const r of t.relations){if(!names[r.target_type.id]||!Number.isFinite(r.multiple)||r.multiple<0||r.multiple>4)throw new Error('属性关系无效');rows[t.name][names[r.target_type.id]]=r.multiple;}if(Object.keys(rows[t.name]).length!==data.count)throw new Error('属性行缺失');}return {rows,aliases,revision:'seerapi:'+data.hash,provider:'seerapi'};}
async function typeChart(){return buildChart(await list('element_type',30));}
function reviewedTargets(m){const entry={13224:['34257fc',3],14734:['7a6e4c8a',4],20444:['95dc4e3e',3],10961:['5866335a',3],10979:['f282522',2],11141:['194546e8',3],13533:['d6a4ddee',3],15423:['5bb55186',4],10759:['13a75776',3],14045:['d84245f6',3],14089:['a021d45c',3],11531:['ba1b7599',4],10175:['461bf54f',5],13870:['fc1058f4',3],16685:['2b38f1c8',4],12090:['dbd41c68',3]}[m.id];return !!entry&&m.hash===entry[0]&&m.atk_num===entry[1];}
function convertMove(m,learn,type,{deferTeamEffects=false}={}){const kind={1:'physical',2:'special',4:'status'}[m.category?.id];if(!kind)throw new Error('未知技能分类');const instances=m.id===20269&&m.hash==='17455ea2'?m.skill_effect.flatMap(e=>e.effect.id===4&&JSON.stringify(e.args)==='[4,100,1,5,100,1]'?[{...e,args:e.args.slice(0,3)},{...e,args:e.args.slice(3),info:'技能使用成功时，100%改变自身命中等级+1'}]:[e]):m.id===20338&&m.hash==='59a84196'?m.skill_effect.flatMap(e=>e.effect.id===5&&JSON.stringify(e.args)==='[4,100,-1,5,100,-1]'?[{...e,args:e.args.slice(0,3)},{...e,args:e.args.slice(3),info:'技能使用成功时，100%改变对手命中等级-1'}]:[e]):m.id===19760&&m.hash==='c5bef174'?m.skill_effect.map(e=>e.effect.id===3&&JSON.stringify(e.args)==='[4]'?{...e,args:[]}:e):m.id===21090&&m.hash==='8bae2c3b'?m.skill_effect.flatMap(e=>e.effect.id===4&&JSON.stringify(e.args)==='[4,100,1,5,100,1]'?[{...e,args:e.args.slice(0,3)},{...e,args:e.args.slice(3),info:'技能使用成功时，100%改变自身命中等级+1'}]:[e]):m.id===23786&&m.hash==='8315356c'?m.skill_effect.map(e=>e.effect.id===58&&JSON.stringify(e.args)==='[2,2]'?{...e,args:[2]}:e):m.id===14486&&m.hash==='c302bc34'?m.skill_effect.map(e=>e.effect.id===500&&JSON.stringify(e.args)==='[50]'?{...e,args:[]}:e):m.id===21076&&m.hash==='850c0775'?m.skill_effect.map(e=>e.effect.id===3&&JSON.stringify(e.args)==='[1]'?{...e,args:[]}:e):m.id===21078&&m.hash==='5cc4870c'?m.skill_effect.flatMap(e=>e.effect.id===5&&JSON.stringify(e.args)==='[4,100,-1,5,100,-1]'?[{...e,args:e.args.slice(0,3)},{...e,args:e.args.slice(3),info:'技能使用成功时，100%改变对手命中等级-1'}]:[e]):m.skill_effect;if(!Array.isArray(instances))throw new Error('技能效果列表缺失');const critical=m.crit_rate==null&&kind==='status'?'1/16':Number.isFinite(m.crit_rate)&&Number.isInteger(m.crit_rate*16/100)?`${m.crit_rate*16/100}/16`:'unknown';const sourceFifth=learn.is_fifth===true;const activationItem=learn.skill_activation_item??null;return {id:int(m.id,'技能ID',1),name:m.name,type,kind,power:int(m.power,'威力'),pp:int(m.max_pp,'PP',1,100),priority:int(m.priority,'先制',-10,10),accuracy:m.accuracy,alwaysHit:m.must_hit===true,critical,effectIds:instances.map(e=>int(e.effect.id,'效果ID',1)),effectInstances:instances.map(e=>({id:e.effect.id,args:e.args,description:e.info})),description:instances.map(e=>e.info??'').join('；'),revision:'seerapi:'+m.hash,hash:m.hash,level:learn.learning_level,fifth:sourceFifth&&!learn.is_special,sourceFlags:{is_fifth:sourceFifth,is_special:learn.is_special===true,skill_activation_item:activationItem,classification:sourceFifth&&learn.is_special?'activation-skill':sourceFifth?'fifth':'regular'},provider:'seerapi',deferredEffects:deferTeamEffects?[...(m.friend_skill_effect??[]).map(e=>({effectId:e.effect?.id??e.id,description:e.info??'友方目标效果',scope:'多精灵待实现'})),...(reviewedTargets(m)?[{field:'atk_num',description:`多目标字段 atk_num=${m.atk_num}；单挑只攻击当前目标一次，多精灵目标选择延期`,scope:'多精灵待实现'}]:[])]:[],limitations:[...(m.atk_num!==1&&!(deferTeamEffects&&reviewedTargets(m))?['多目标攻击尚未适配']:[]),...(m.hide_effect&&!((m.id===13547&&m.hash==='b130cfa6'&&m.hide_effect.id===2)||(m.id===12089&&m.hash==='ccb4f2de'&&m.hide_effect.id===9))?['隐藏效果尚未适配']:[]),...(m.friend_skill_effect?.length&&!deferTeamEffects?['友方目标效果尚未适配']:[])]};}
async function species(id){if(!/^\d{1,6}$/.test(String(id)))throw new Error('精灵编号无效');const p=await api('pet',id);if(!Array.isArray(p.skill)||!Array.isArray(p.soulmark))throw new Error('精灵数据不完整');const chart=await typeChart(),types=new Map();async function typename(ref){if(!types.has(ref.id)){const t=await api('element_type_combination',ref.id);const elements=await list('element_type',30),names=Object.fromEntries(elements.results.map(x=>[x.id,x.name]));const parts=[names[t.primary?.id],...(t.secondary?[names[t.secondary.id]]:[])];if(parts.some(x=>!x))throw new Error('复合属性成分缺失');chart.aliases[t.name]=parts;types.set(ref.id,t.name);}return types.get(ref.id);}
 const type=await typename(p.type),moves=[],effects=[],seen=new Set();for(const learn of p.skill){const m=await api('skill',learn.skill.id);moves.push(convertMove(m,learn,await typename(m.type),{deferTeamEffects:(p.id>=2987&&p.id<=3043)||[3046,3056,3066,3075,3079,3082,3102,3106,3141,3142].includes(p.id)}));for(const e of m.skill_effect??[])if(!seen.has(e.effect.id)){const entry=await api('skill_effect_type',e.effect.id);effects.push({id:entry.id,argsNum:entry.args_num,template:entry.info,revision:'seerapi:'+entry.hash});seen.add(entry.id);}}
 const souls=[];for(const ref of p.soulmark){const soul=await api('soulmark',ref.id);souls.push({id:soul.id,description:soul.desc,hash:soul.hash,eid:soul.effect?.effect?.id,args:soul.effect?.effect_args});}
 const baseStats=p.base_stats;if(baseStats?.percent)throw new Error('百分比种族值尚未支持');return {id:p.id,name:p.name,type,base:Object.fromEntries(Object.entries({maxHp:'hp',atk:'atk',def:'def',spa:'sp_atk',spd:'sp_def',spe:'spd'}).map(([k,v])=>[k,int(baseStats?.[v],v,1,999)])),moves,effects,souls,missingEffects:[],typeChart:chart,source:{provider:'seerapi',url:base+'pet/'+p.id,revision:p.hash,loadedAt:new Date().toISOString()}};
}
async function search(q){if(!/^[\p{L}\p{N}·\s-]{1,40}$/u.test(q))throw new Error('请输入精灵名称或编号');const data=/^\d+$/.test(q)?{results:[await api('pet',Number(q))]}:await api('pet',null,{name:q,limit:20,expand:true});if(!Array.isArray(data.results))throw new Error('搜索数据不完整');return {results:data.results.map(p=>({id:p.id,name:p.name,type:''})),limit:20};}
module.exports={search,species,typeChart,convertMove,buildChart,status:client.status};

