function seedCase(entry,check,options={}){for(let seed=0;seed<128;seed++){const s=make(entry,{...options,seed}),out=turn(s);if(check(out,s))return {s,out,seed};}assert.fail('找不到所需真实随机分支 '+entry.key);}
