 // Attack selection removes the previous round's status immunity before effects.
 const b=make(basic,{soul,seed:8,opponentEffect:pick(889)[0]});timer(b,0,'doubleDamage');const q=turn(b,10127,900023);assert.ok(q.fighters[0].ailments['感染']||q.fighters[0].ailments['中毒']||q.fighters[1].pp[key(900023)]===0);const reset=turn(o,IDLE,HIT);assert.equal(reset.fighters[0].soulState.jasmineStatus,false);
