 const plain=make(e,{soul:1825,hp:1000}),core=structuredClone(plain);core.fighters[0].soulState.jasmineCore=3;const a=turn(plain),b=turn(core);assert.equal(a.fighters[0].lastAttackDamage,b.fighters[0].lastAttackDamage);assert.equal(a.fighters[1].hp-b.fighters[1].hp,30);
 const percent=make(pick(977)[0],{soul:1825,hp:4500});percent.fighters[0].soulState.jasmineCore=3;const p=turn(percent);assert.equal(9000-p.fighters[1].hp-p.fighters[0].lastAttackDamage,2925);const old=E.resolveTurn(make(e,{soul:909}),[key(e.moveId),'potion:pp']);assert.equal(old.fighters[0].soulState.jasmineCore,undefined);
